import numpy as np

def cost_table(y, x, costs):
    """[(cost in bp, total P&L to 2 places, Sharpe to 3 places), ...] from the reference backtest."""
    rows = []
    for c in costs:
        pnl, sharpe, trades = backtest(y, x, cost_bp=c)
        rows.append((c, round(float(pnl.sum()), 2), round(float(sharpe), 3)))
    return rows


def breakeven_bp(y, x):
    """The cost in bp at which total P&L is zero, to 1 place. The trades do not depend on the cost."""
    gross = backtest(y, x, cost_bp=0)[0].sum()
    per_bp = gross - backtest(y, x, cost_bp=1)[0].sum()
    return round(float(gross / per_bp), 1)
